/* ============================================================================
 * 功能区：会话与角色核心 / builtinAvatars
 * 职责：内置角色卡的默认头像数据；只用于补齐本机头像表，不进入 system 或对话。
 * 分区：01 类型、契约与依赖；
 *    02 核心实现：LEGACY_AVATAR_DIGESTS、digestAvatar、ensureBuiltinCardAvatars
 * 关联：无内部依赖；被 scripts/test-roleplay、services/settings 引用。
 * 导出：BUILTIN_CARD_AVATARS、BUILTIN_CARD_AVATAR_IDS、ensureBuiltinCardAvatars
 * 边界：只处理聊天领域的数据、状态转换与提示词装配；不直接渲染视图，不发起职责外的网络请求。
 * ========================================================================== */

/* ---- 01 类型、契约与依赖 ---- */
/**
 * 内置头像以 256px WebP data URL 内嵌，避免应用启动时依赖网络或异步解码。
 * 大肥鱼、鲸鱼娘头像使用社区二创图，来源与许可见 assets/fanart/SOURCES.md。
 */
export const BUILTIN_CARD_AVATARS: Record<string, string> = {
  'builtin:dafeiyu': 'data:image/webp;base64,',
  'builtin:whale-girl': 'data:image/webp;base64,',
  'builtin:catgirl': 'data:image/webp;base64,',
  'builtin:jianghu': 'data:image/webp;base64,',
  'builtin:xianxia': 'data:image/webp;base64,',
  'builtin:urban': 'data:image/webp;base64,',
  'builtin:midnight-sister': 'data:image/webp;base64,',
}

/** 内置头像只补这些 id；新增内置卡时在这里同步登记 */
export const BUILTIN_CARD_AVATAR_IDS = Object.keys(BUILTIN_CARD_AVATARS)

/**
 * 0.9.0 之前内置卡使用的旧原版鲸鱼头像指纹。
 * 只替换与这些指纹完全一致的头像，用户自己上传或换过的头像不动。
 */
const LEGACY_AVATAR_DIGESTS: Record<string, string> = {
  'builtin:dafeiyu': '919e4e78',
  'builtin:whale-girl': '80bc734e',
}

/* ---- 02 核心实现：LEGACY_AVATAR_DIGESTS、digestAvatar、ensureBuiltinCardAvatars ---- */
/** FNV-1a 32 位摘要，只用于识别旧内置头像，避免把整段 base64 留在代码里 */
const digestAvatar = (value: string): string => {
  let hash = 0x811c9dc5
  for (let i = 0; i < value.length; i += 1) {
    hash ^= value.charCodeAt(i)
    hash = Math.imul(hash, 0x01000193)
  }
  return (hash >>> 0).toString(16).padStart(8, '0')
}

/**
 * 只补齐“当前存在、用户没有移除过、也还没有自定义头像”的内置卡。
 * 若头像仍是旧版内置鲸鱼图，则升级为当前二创头像；用户自定义头像一律保留。
 * removed 是用户显式移除过头像的墓碑。
 */
export const ensureBuiltinCardAvatars = (
  avatars: Record<string, string>,
  cardIds: string[],
  removed: string[] = []
): { avatars: Record<string, string>; added: number; replaced: number } => {
  const next = { ...avatars }
  let added = 0
  let replaced = 0
  for (const id of BUILTIN_CARD_AVATAR_IDS) {
    if (!cardIds.includes(id) || removed.includes(id)) {
      continue
    }
    if (!Object.prototype.hasOwnProperty.call(next, id)) {
      next[id] = BUILTIN_CARD_AVATARS[id]
      added += 1
      continue
    }
    if (next[id] === BUILTIN_CARD_AVATARS[id]) {
      continue
    }
    if (digestAvatar(next[id]) !== LEGACY_AVATAR_DIGESTS[id]) {
      continue
    }
    next[id] = BUILTIN_CARD_AVATARS[id]
    replaced += 1
  }
  return { avatars: next, added, replaced }
}
